/* ---------- Petits utilitaires ---------- */

function pickUnit(ms) {
  if (ms && ms % UNITS.h.ms === 0) return "h";
  if (ms && ms % UNITS.m.ms === 0) return "m";
  return "s";
}

function fmtNum(n) {
  return String(Math.round(n * 100) / 100);
}

function fmtDuration(ms) {
  const total = ms / 1000;
  const h = Math.floor(total / 3600);
  const m = Math.floor((total % 3600) / 60);
  const s = Math.round((total % 60) * 100) / 100;
  const parts = [];
  if (h) parts.push(h + " h");
  if (m) parts.push(m + " min");
  if (s || !parts.length) parts.push(fmtNum(s) + " s");
  return parts.join(" ");
}

// Petit constructeur DOM : h("div", { class: "x", onClick: fn }, enfants...)
function h(tag, props = {}, ...kids) {
  const el = document.createElement(tag);
  for (const [k, v] of Object.entries(props)) {
    if (v === undefined || v === null) continue;
    if (k === "class") el.className = v;
    else if (k === "style") el.style.cssText = v;
    else if (k.startsWith("on")) el.addEventListener(k.slice(2).toLowerCase(), v);
    else if (k in el) el[k] = v;
    else el.setAttribute(k, v);
  }
  for (const kid of kids.flat()) {
    if (kid === null || kid === undefined || kid === false) continue;
    el.append(kid.nodeType ? kid : document.createTextNode(String(kid)));
  }
  return el;
}

