module.exports = class StatusRotator {
  constructor(meta) {
    this.meta = meta;
    this.animation = [];
    this.timeout = DEFAULT_TIMEOUT;
    this.timeoutUnit = "s";
    this.randomize = false;
    this.loop = null;
    this.running = false;
    this.paused = false;
    this.index = 0;
    this.currentStatus = null;
    this.nextChangeAt = null;
    this.restAPI = null;
    this.proto = null;
    this.warned = false;
  }

  /* ---------- Cycle de vie ---------- */

  start() {
    this.running = true;
    this.paused = false;
    this.warned = false;
    this.loadSettings();

    if (!this.getActive().length) {
      BdApi.UI.showToast("StatusRotator : aucun statut actif. Va dans Paramètres > Plugins.", { type: "info" });
      return;
    }
    this.index = 0;
    this.tick();
  }

  stop() {
    this.running = false;
    this.paused = false;
    this.clearTimer();
    this.currentStatus = null;
    this.setStatus(null);
  }

  restart() {
    this.clearTimer();
    this.start();
  }

  pause() {
    this.paused = true;
    this.clearTimer();
  }

  resume() {
    if (!this.running) return;
    this.paused = false;
    this.tick();
  }

  clearTimer() {
    if (this.loop) clearTimeout(this.loop);
    this.loop = null;
    this.nextChangeAt = null;
  }

  loadSettings() {
    const saved = BdApi.Data.load(this.meta.name, "animation");
    this.animation = Array.isArray(saved) && saved.length ? saved : DEFAULT_ANIMATION.map(s => ({ ...s }));
    this.timeout = Math.max(MIN_TIMEOUT, parseInt(BdApi.Data.load(this.meta.name, "timeout")) || DEFAULT_TIMEOUT);
    this.timeoutUnit = BdApi.Data.load(this.meta.name, "timeoutUnit") || pickUnit(this.timeout);
    this.randomize = !!BdApi.Data.load(this.meta.name, "randomize");
  }

  getActive() {
    return this.animation.filter(s => s.enabled !== false && (s.text || s.emoji_name));
  }

  /* ---------- Boucle d'animation ---------- */

  tick() {
    if (!this.running || this.paused) return;

    const active = this.getActive();
    if (!active.length) return;

    this.index %= active.length;
    const step = active[this.index];

    const status = {};
    if (step.text) status.text = String(step.text).slice(0, MAX_TEXT);
    if (step.emoji_name) status.emoji_name = String(step.emoji_name);
    if (step.emoji_id) status.emoji_id = String(step.emoji_id);

    this.currentStatus = status;
    this.setStatus(Object.keys(status).length ? status : null);

    const delay = Math.max(MIN_TIMEOUT, parseInt(step.timeout) || this.timeout);

    if (this.randomize && active.length > 1) {
      let next;
      do { next = Math.floor(Math.random() * active.length); } while (next === this.index);
      this.index = next;
    } else {
      this.index++;
    }

    this.nextChangeAt = Date.now() + delay;
    this.loop = setTimeout(() => this.tick(), delay);
  }

  /* ---------- Recherche des modules Discord ---------- */

  getProtoSettings() {
    if (this.proto) return this.proto;

    const W = BdApi.Webpack;
    const isProto = (m) => m && typeof m.updateAsync === "function";
    const attempts = [
      () => W.getModule((m) => isProto(m) && m.ProtoClass?.typeName?.includes("PreloadedUserSettings"), { searchExports: true }),
      () => W.getByKeys("PreloadedUserSettingsActionCreators")?.PreloadedUserSettingsActionCreators,
      () => W.getModule((m) => isProto(m) && typeof m.getCurrentValue === "function", { searchExports: true })
    ];

    for (const attempt of attempts) {
      try {
        const found = attempt();
        if (isProto(found)) {
          this.proto = found;
          return found;
        }
      } catch (e) {}
    }
    return null;
  }

  getRestAPI() {
    if (this.restAPI) return this.restAPI;

    const W = BdApi.Webpack;
    const isRest = (m) => m && typeof m.patch === "function" && typeof m.post === "function";
    const attempts = [
      () => W.getModule((m) => isRest(m) && typeof m.getAPIBaseURL === "function", { searchExports: true }),
      () => W.getModule((m) => isRest(m) && typeof m.put === "function" && typeof m.del === "function", { searchExports: true }),
      () => W.getByKeys("getAPIBaseURL", "patch", "post")
    ];

    for (const attempt of attempts) {
      try {
        const found = attempt();
        if (isRest(found)) {
          this.restAPI = found;
          return found;
        }
      } catch (e) {}
    }
    return null;
  }

  /* ---------- Envoi à Discord ---------- */

  async setStatus(status) {
    // Méthode principale : paramètres "proto" de Discord
    try {
      const proto = this.getProtoSettings();
      if (proto) {
        await proto.updateAsync("status", (s) => {
          if (status) {
            s.customStatus = {
              text: status.text || "",
              emojiId: status.emoji_id || "0",
              emojiName: status.emoji_name || "",
              expiresAtMs: "0"
            };
          } else {
            s.customStatus = undefined;
          }
        }, 0);
        console.log("[StatusRotator] statut envoyé via proto :", status);
        return;
      }
    } catch (e) {
      console.warn("[StatusRotator] méthode proto échouée, essai de l'ancienne méthode :", e);
    }

    return this.setStatusREST(status);
  }

  async setStatusREST(status) {
    // Solution de secours : l'API interne de Discord (aucun token n'est lu ni envoyé par le plugin)
    try {
      const api = this.getRestAPI();
      if (!api) throw new Error("Impossible de trouver les modules de Discord (une mise à jour du plugin est peut-être nécessaire).");
      await api.patch({ url: "/users/@me/settings", body: { custom_status: status } });
    } catch (e) {
      console.error("[StatusRotator]", e);
      if (e?.status === 429) return this.fail("Durée trop courte, augmente le temps entre les statuts.");
      this.fail(e?.message || String(e));
    }
  }

  fail(msg) {
    if (this.warned) return;
    this.warned = true;
    BdApi.UI.showToast(`StatusRotator : ${msg}`, { type: "error" });
  }

  /* ---------- Interface de réglages ---------- */

  getSettingsPanel() {
    const wrapper = h("div", { class: "sr-wrapper" });
    this.buildPanel(wrapper);
    return wrapper;
  }

  buildPanel(wrapper, override) {
    if (wrapper._timer) clearInterval(wrapper._timer);
    wrapper.textContent = "";

    // --- État local (copie de travail, enregistrée seulement au clic sur "Enregistrer") ---
    this.loadSettings();
    const base = override || {
      animation: this.animation,
      timeout: this.timeout,
      unit: this.timeoutUnit,
      randomize: this.randomize
    };
    const state = {
      animation: base.animation.map(s => {
        const c = { enabled: true, ...s };
        if (c.timeout && !c.timeoutUnit) c.timeoutUnit = pickUnit(c.timeout);
        return c;
      }),
      timeout: base.timeout,
      unit: base.unit,
      randomize: base.randomize
    };

    const root = h("div", { class: "sr-root" }, h("style", {}, CSS));
    wrapper.append(root);

    const dirtyBadge = h("span", { class: "sr-dirty", style: "display:none" }, "● Modifications non enregistrées");
    const markDirty = () => { dirtyBadge.style.display = ""; };

    /* ----- En-tête ----- */
    root.append(
      h("div", {},
        h("div", { class: "sr-title" }, "StatusRotator"),
        h("div", { class: "sr-sub" }, "Ton statut change tout seul, dans l'ordre ou au hasard.")
      )
    );

    /* ----- Aperçu en direct ----- */
    const liveEmoji = h("span", { class: "sr-live-emoji" });
    const liveText = h("div", { class: "sr-live-text" });
    const liveInfo = h("div", { class: "sr-live-info" });
    const pauseBtn = h("button", { class: "sr-btn", onClick: () => {
      if (!this.running) return;
      this.paused ? this.resume() : this.pause();
      updateLive();
    } }, "⏸ Pause");
    const skipBtn = h("button", { class: "sr-btn", title: "Passer au statut suivant", onClick: () => {
      if (!this.running) return;
      this.clearTimer();
      this.paused = false;
      this.tick();
      updateLive();
    } }, "⏭ Suivant");

    const updateLive = () => {
      const cs = this.currentStatus;
      liveEmoji.textContent = cs?.emoji_name || "💬";
      liveText.textContent = cs?.text || (this.running ? "—" : "Plugin désactivé");
      if (!this.running) liveInfo.textContent = "Le plugin est désactivé.";
      else if (this.paused) liveInfo.textContent = "En pause.";
      else if (this.nextChangeAt) {
        const secs = Math.max(0, Math.ceil((this.nextChangeAt - Date.now()) / 1000));
        liveInfo.textContent = `Prochain changement dans ${fmtDuration(secs * 1000)}`;
      } else liveInfo.textContent = "";
      pauseBtn.textContent = this.paused ? "▶ Reprendre" : "⏸ Pause";
    };

    root.append(
      h("div", { class: "sr-card" },
        h("div", { class: "sr-card-title" }, "Statut actuel"),
        h("div", { class: "sr-live" },
          h("div", { class: "sr-bubble" }, liveEmoji, liveText),
          pauseBtn, skipBtn,
          liveInfo
        )
      )
    );
    updateLive();

    let ticks = 0;
    wrapper._timer = setInterval(() => {
      ticks++;
      if (!root.isConnected && ticks > 5) { clearInterval(wrapper._timer); return; }
      updateLive();
    }, 1000);

    /* ----- Contrôle de durée (nombre + unité), réutilisé partout ----- */
    const durationControl = (getVal, setVal) => {
      const cur = getVal();
      const num = h("input", {
        type: "number", class: "sr-input sr-num", min: "0", step: "any",
        value: fmtNum(cur.ms / UNITS[cur.unit].ms)
      });
      const sel = h("select", { class: "sr-input sr-select" },
        Object.entries(UNITS).map(([k, u]) => h("option", { value: k, selected: k === cur.unit }, u.label))
      );
      const hint = h("div", { class: "sr-hint" });

      const refreshHint = (ms) => {
        if (ms < MIN_TIMEOUT) {
          hint.className = "sr-hint sr-warn";
          hint.textContent = "⚠ Minimum 10 secondes (Discord bloque en dessous).";
        } else {
          hint.className = "sr-hint";
          hint.textContent = "= " + fmtDuration(ms);
        }
      };

      const apply = () => {
        const v = parseFloat(num.value);
        const unit = sel.value;
        const ms = isFinite(v) ? Math.round(v * UNITS[unit].ms) : 0;
        setVal(ms, unit);
        refreshHint(ms);
        markDirty();
      };
      num.addEventListener("input", apply);
      sel.addEventListener("change", apply);
      refreshHint(cur.ms);

      const sync = () => {
        const c = getVal();
        num.value = fmtNum(c.ms / UNITS[c.unit].ms);
        sel.value = c.unit;
        refreshHint(c.ms);
      };

      return { el: h("div", { class: "sr-field" }, h("div", { class: "sr-row" }, num, sel), hint), sync };
    };

    /* ----- Réglages généraux ----- */
    const globalDuration = durationControl(
      () => ({ ms: state.timeout, unit: state.unit }),
      (ms, unit) => { state.timeout = ms; state.unit = unit; }
    );

    const orderSelect = h("select", { class: "sr-input sr-select", onChange: (e) => {
      state.randomize = e.target.value === "random";
      markDirty();
    } },
      h("option", { value: "order", selected: !state.randomize }, "Dans l'ordre de la liste"),
      h("option", { value: "random", selected: state.randomize }, "Aléatoire")
    );

    const chips = h("div", { class: "sr-chips" },
      QUICK_DURATIONS.map(q => h("button", { class: "sr-chip", onClick: () => {
        state.timeout = q.ms;
        state.unit = q.unit;
        globalDuration.sync();
        markDirty();
      } }, q.label))
    );

    root.append(
      h("div", { class: "sr-card" },
        h("div", { class: "sr-card-title" }, "Réglages généraux"),
        h("div", { class: "sr-row", style: "align-items:flex-start;gap:24px" },
          h("div", { class: "sr-field" },
            h("div", { class: "sr-label" }, "Durée de chaque statut"),
            globalDuration.el,
            chips
          ),
          h("div", { class: "sr-field" },
            h("div", { class: "sr-label" }, "Ordre"),
            orderSelect
          )
        )
      )
    );

    /* ----- Liste des statuts ----- */
    const list = h("div", { class: "sr-list" });
    const countBadge = h("span", {});
    let dragFrom = null;

    const move = (from, to) => {
      const [item] = state.animation.splice(from, 1);
      state.animation.splice(to, 0, item);
      renderList();
      markDirty();
    };

    const renderCard = (item, i) => {
      const card = h("div", { class: "sr-item" + (item.enabled === false ? " sr-off" : "") });

      // --- En-tête de la carte ---
      const handle = h("span", { class: "sr-handle", title: "Glisser pour réorganiser" }, "⋮⋮");
      handle.addEventListener("mousedown", () => { card.draggable = true; });
      handle.addEventListener("mouseup", () => { card.draggable = false; });

      const sw = h("label", { class: "sr-switch", title: "Activer / désactiver ce statut" },
        h("input", { type: "checkbox", checked: item.enabled !== false, onChange: (e) => {
          item.enabled = e.target.checked;
          card.classList.toggle("sr-off", !item.enabled);
          markDirty();
        } }),
        h("span", { class: "sr-slider" })
      );

      const head = h("div", { class: "sr-item-head" },
        handle,
        h("span", { class: "sr-badge" }, "#" + (i + 1)),
        sw,
        h("span", { class: "sr-spacer" }),
        h("button", { class: "sr-btn sr-icon", title: "Tester ce statut maintenant", onClick: () => {
          const st = {};
          if (item.text) st.text = item.text.slice(0, MAX_TEXT);
          if (item.emoji_name) st.emoji_name = item.emoji_name;
          if (item.emoji_id) st.emoji_id = item.emoji_id;
          this.currentStatus = st;
          this.setStatus(Object.keys(st).length ? st : null);
          BdApi.UI.showToast("Statut appliqué (la rotation continue ensuite).", { type: "info" });
          updateLive();
        } }, "▶"),
        h("button", { class: "sr-btn sr-icon", title: "Monter", disabled: i === 0, onClick: () => move(i, i - 1) }, "↑"),
        h("button", { class: "sr-btn sr-icon", title: "Descendre", disabled: i === state.animation.length - 1, onClick: () => move(i, i + 1) }, "↓"),
        h("button", { class: "sr-btn sr-icon", title: "Dupliquer", onClick: () => {
          state.animation.splice(i + 1, 0, { ...item });
          renderList();
          markDirty();
        } }, "⧉"),
        h("button", { class: "sr-btn sr-icon sr-danger", title: "Supprimer", onClick: () => {
          state.animation.splice(i, 1);
          renderList();
          markDirty();
        } }, "🗑")
      );

      // --- Emoji + texte ---
      const emojiBtn = h("button", { class: "sr-emoji-btn", title: "Choisir un emoji" }, item.emoji_name || "＋");

      const setEmoji = (value) => {
        item.emoji_name = value;
        if (!value) delete item.emoji_id;
        emojiBtn.textContent = value || "＋";
        markDirty();
      };

      let pop = null;
      const closePop = () => {
        if (pop) { pop.remove(); pop = null; }
        document.removeEventListener("mousedown", outside, true);
      };
      const outside = (e) => { if (pop && !pop.contains(e.target) && e.target !== emojiBtn) closePop(); };

      const customEmoji = h("input", { class: "sr-input", placeholder: "Coller n'importe quel emoji ici + Entrée (Win + ;)", style: "width:100%" });
      customEmoji.addEventListener("keydown", (e) => {
        if (e.key === "Enter" && customEmoji.value.trim()) { setEmoji(customEmoji.value.trim()); closePop(); }
      });

      const buildPicker = () => {
        const search = h("input", { class: "sr-input", placeholder: "Rechercher : couronne, manette, feu, cœur, cat…", style: "width:100%" });
        const scroll = h("div", { class: "sr-scroll" });
        const tabs = h("div", { class: "sr-tabs" });
        const sections = [];
        const all = [];

        const pick = (em) => { setEmoji(em); closePop(); };
        const makeBtn = (e) => h("button", { title: e.name, onClick: () => pick(e.em) }, e.em);

        // Retire accents et majuscules : "Couronne", "couronné", "COURONNE" marchent pareil
        const fold = (t) => t.toLowerCase().replace(/œ/g, "oe").replace(/æ/g, "ae").normalize("NFD").replace(/[\u0300-\u036f]/g, "");

        const browse = h("div", {});
        const results = h("div", { style: "display:none" });
        scroll.append(browse, results);

        EMOJI_DATA.forEach((g) => {
          const grid = h("div", { class: "sr-grid" });
          for (const entry of g.e) {
            const [em, name, kw] = entry.split("|");
            const item = { em, name, label: fold(name), kw: fold(name + " " + kw) };
            all.push(item);
            grid.append(makeBtn(item));
          }
          const section = h("div", {}, h("div", { class: "sr-gtitle" }, g.l), grid);
          sections.push(section);
          browse.append(section);
          tabs.append(h("button", { class: "sr-tab", title: g.l, onClick: () => {
            search.value = "";
            applySearch();
            scroll.scrollTop = section.offsetTop - scroll.offsetTop;
          } }, g.i));
        });

        // Les meilleurs résultats d'abord : nom exact > début de mot > dans le nom > mots-clés
        const score = (it, words, q) => {
          let best = 9;
          for (const w of words) {
            let sc;
            if (it.label === q) sc = 0;
            else if (it.label.split(/[\s'-]+/).includes(w)) sc = 1;
            else if (it.label.split(/[\s'-]+/).some(x => x.startsWith(w))) sc = 2;
            else if (it.label.includes(w)) sc = 3;
            else if (it.kw.split(" ").includes(w)) sc = 4;
            else if (it.kw.includes(w)) sc = 5;
            else return -1;
            best = Math.min(best, sc);
          }
          return best;
        };

        function applySearch() {
          const raw = search.value.trim();
          const q = fold(raw);
          const words = q.split(/\s+/).filter(Boolean);
          scroll.scrollTop = 0;

          if (!words.length) {
            results.style.display = "none";
            browse.style.display = "";
            return;
          }

          const found = [];
          for (const it of all) {
            const sc = it.em === raw ? 0 : score(it, words, q);
            if (sc >= 0) found.push([sc, it]);
          }
          found.sort((x, y) => x[0] - y[0]);

          results.textContent = "";
          browse.style.display = "none";
          results.style.display = "";
          if (!found.length) {
            results.append(h("div", { class: "sr-empty" }, "Aucun emoji trouvé. Essaie un autre mot, ou colle l'emoji dans la case du bas."));
            return;
          }
          results.append(h("div", { class: "sr-grid" }, found.slice(0, 300).map(([, it]) => makeBtn(it))));
        }
        search.addEventListener("input", applySearch);

        return { search, scroll, tabs };
      };

      emojiBtn.addEventListener("click", () => {
        if (pop) return closePop();
        const { search, scroll, tabs } = buildPicker();
        pop = h("div", { class: "sr-pop" },
          search,
          tabs,
          scroll,
          customEmoji,
          h("button", { class: "sr-btn", onClick: () => { setEmoji(""); closePop(); } }, "Aucun emoji")
        );
        main.append(pop);
        document.addEventListener("mousedown", outside, true);
        search.focus();
      });

      const counter = h("span", { class: "sr-count" });
      const updateCount = () => {
        const n = (item.text || "").length;
        counter.textContent = `${n}/${MAX_TEXT}`;
        counter.className = "sr-count" + (n > MAX_TEXT - 10 ? " sr-warn" : "");
      };
      const textInput = h("input", {
        class: "sr-input sr-text", placeholder: "Ton texte de statut…", maxLength: MAX_TEXT,
        value: item.text || ""
      });
      textInput.addEventListener("input", () => {
        item.text = textInput.value;
        updateCount();
        markDirty();
      });
      updateCount();

      const main = h("div", { class: "sr-item-main", style: "position:relative" },
        emojiBtn,
        h("div", { class: "sr-text-wrap" }, textInput, counter)
      );

      // --- Durée de ce statut ---
      const custom = !!item.timeout;
      const footParts = [
        h("label", { class: "sr-check" },
          h("input", { type: "checkbox", checked: custom, onChange: (e) => {
            if (e.target.checked) { item.timeout = state.timeout; item.timeoutUnit = state.unit; }
            else { delete item.timeout; delete item.timeoutUnit; }
            renderList();
            markDirty();
          } }),
          "Durée personnalisée"
        )
      ];
      if (custom) {
        const ctrl = durationControl(
          () => ({ ms: item.timeout, unit: item.timeoutUnit || pickUnit(item.timeout) }),
          (ms, unit) => { item.timeout = ms; item.timeoutUnit = unit; }
        );
        footParts.push(ctrl.el);
      } else {
        footParts.push(h("span", { class: "sr-hint" }, "Utilise la durée générale (" + fmtDuration(state.timeout) + ")"));
      }

      // --- Mode avancé (emoji Nitro) ---
      const nitroInput = h("input", {
        class: "sr-input", placeholder: "ID de l'emoji Nitro (optionnel)", value: item.emoji_id || "", style: "width:100%"
      });
      nitroInput.addEventListener("input", () => { item.emoji_id = nitroInput.value.trim(); markDirty(); });
      const nitroBox = h("div", { class: "sr-field", style: "display:" + (item.emoji_id ? "flex" : "none") },
        h("div", { class: "sr-label" }, "Emoji personnalisé (Nitro) : mets son nom dans le bouton emoji et son ID ici"),
        nitroInput
      );
      const nitroToggle = h("button", { class: "sr-chip", onClick: () => {
        nitroBox.style.display = nitroBox.style.display === "none" ? "flex" : "none";
      } }, "Avancé : emoji Nitro");

      const foot = h("div", { class: "sr-item-foot" }, footParts, h("span", { class: "sr-spacer" }), nitroToggle);

      card.append(head, main, foot, nitroBox);

      // --- Glisser-déposer ---
      card.addEventListener("dragstart", (e) => {
        dragFrom = i;
        card.classList.add("sr-dragging");
        e.dataTransfer.effectAllowed = "move";
        e.dataTransfer.setData("text/plain", String(i));
      });
      card.addEventListener("dragend", () => {
        dragFrom = null;
        card.draggable = false;
        card.classList.remove("sr-dragging");
        list.querySelectorAll(".sr-over").forEach(c => c.classList.remove("sr-over"));
      });
      card.addEventListener("dragover", (e) => {
        if (dragFrom === null) return;
        e.preventDefault();
        card.classList.add("sr-over");
      });
      card.addEventListener("dragleave", () => card.classList.remove("sr-over"));
      card.addEventListener("drop", (e) => {
        e.preventDefault();
        if (dragFrom === null || dragFrom === i) return;
        move(dragFrom, i);
      });

      return card;
    };

    const renderList = () => {
      list.textContent = "";
      countBadge.textContent = state.animation.length
        ? `${state.animation.length} statut${state.animation.length > 1 ? "s" : ""}`
        : "";
      if (!state.animation.length) {
        list.append(h("div", { class: "sr-empty" }, "Aucun statut pour l'instant. Clique sur « + Ajouter un statut »."));
        return;
      }
      state.animation.forEach((item, i) => list.append(renderCard(item, i)));
    };

    const addBtn = h("button", { class: "sr-btn sr-primary", onClick: () => {
      state.animation.push({ text: "", emoji_name: "", enabled: true });
      renderList();
      markDirty();
      list.lastElementChild?.querySelector(".sr-text")?.focus();
    } }, "+ Ajouter un statut");

    root.append(
      h("div", { class: "sr-card" },
        h("div", { class: "sr-card-title" }, h("span", {}, "Tes statuts ", countBadge), addBtn),
        list
      )
    );
    renderList();

    /* ----- Pied de page : enregistrer / annuler / réinitialiser ----- */
    const save = () => {
      const cleaned = [];
      let clamped = false;

      for (const s of state.animation) {
        const text = (s.text || "").trim();
        const emoji = (s.emoji_name || "").trim();
        const id = (s.emoji_id || "").trim();
        if (!text && !emoji) continue;

        const o = { enabled: s.enabled !== false };
        if (text) o.text = text.slice(0, MAX_TEXT);
        if (emoji) o.emoji_name = emoji;
        if (id) o.emoji_id = id;
        if (s.timeout) {
          if (s.timeout < MIN_TIMEOUT) clamped = true;
          o.timeout = Math.max(MIN_TIMEOUT, s.timeout);
          o.timeoutUnit = s.timeoutUnit || pickUnit(o.timeout);
        }
        cleaned.push(o);
      }

      if (!cleaned.length) {
        BdApi.UI.showToast("Ajoute au moins un statut avant d'enregistrer.", { type: "error" });
        return;
      }

      if (state.timeout < MIN_TIMEOUT) clamped = true;
      const globalMs = Math.max(MIN_TIMEOUT, state.timeout);

      BdApi.Data.save(this.meta.name, "animation", cleaned);
      BdApi.Data.save(this.meta.name, "timeout", globalMs);
      BdApi.Data.save(this.meta.name, "timeoutUnit", state.unit);
      BdApi.Data.save(this.meta.name, "randomize", state.randomize);

      BdApi.UI.showToast(
        clamped ? "Enregistré — certaines durées ont été remontées à 10 secondes (minimum)." : "StatusRotator : réglages enregistrés !",
        { type: clamped ? "warning" : "success" }
      );

      this.restart();
      this.buildPanel(wrapper);
    };

    const resetDefaults = () => {
      BdApi.UI.showConfirmationModal(
        "Réinitialiser",
        "Remettre les statuts et la durée par défaut ? (rien n'est enregistré tant que tu ne cliques pas sur « Enregistrer »)",
        {
          confirmText: "Réinitialiser",
          cancelText: "Annuler",
          danger: true,
          onConfirm: () => {
            this.buildPanel(wrapper, {
              animation: DEFAULT_ANIMATION.map(s => ({ ...s })),
              timeout: DEFAULT_TIMEOUT,
              unit: "s",
              randomize: false
            });
            const badge = wrapper.querySelector(".sr-dirty");
            if (badge) badge.style.display = "";
          }
        }
      );
    };

    root.append(
      h("div", { class: "sr-footer" },
        h("button", { class: "sr-btn sr-primary", onClick: save }, "💾 Enregistrer"),
        h("button", { class: "sr-btn", onClick: () => this.buildPanel(wrapper) }, "Annuler les modifications"),
        h("button", { class: "sr-btn sr-danger", onClick: resetDefaults }, "Réinitialiser"),
        h("span", { class: "sr-spacer" }),
        dirtyBadge
      )
    );
  }
};
